function countUndoubtedlyLucky(limit) {
    const s = limit.toString();
    const len = s.length;

    // Precompute powers of 10 up to 10 digits
    const pow10 = Array(11).fill(0n);
    pow10[0] = 1n;
    for (let i = 1; i <= 10; i++) pow10[i] = pow10[i - 1] * 10n;

    let total = 0n;

    // Count numbers with fewer digits than n
    for (let d = 1; d < len; d++) {
        const countPairs = 45n + 10n * BigInt(d - 1); // 10 + 9 + 10*(d-1)
        total += countPairs * pow10[d - 1];
    }

    // Count numbers with same length using digit DP
    // dp[pos][mask][tight][started]
    // mask: bit 0 for digit x used, bit 1 for digit y used
    const memo = new Map();

    function dfs(pos, mask, tight, started, x, y) {
        if (pos === len) {
            if (!started) return 0n;
            // at least one digit, and digits used are subset of {x,y}
            return 1n;
        }
        const key = `${pos},${mask},${tight?1:0},${started?1:0},${x},${y}`;
        if (!tight && memo.has(key)) return memo.get(key);

        const limitDigit = Number(s[pos]);
        let res = 0n;

        for (let d = 0; d <= (tight ? limitDigit : 9); d++) {
            const ntight = tight && (d === limitDigit);
            const nstarted = started || d !== 0;

            if (!nstarted) {
                // still leading zeros, no digits chosen yet
                res += dfs(pos + 1, 0, ntight, false, x, y);
            } else {
                // digit must be either x or y
                if (d !== x && d !== y) continue;
                let nmask = mask;
                if (d === x) nmask |= 1;
                if (d === y) nmask |= 2;
                res += dfs(pos + 1, nmask, ntight, true, x, y);
            }
        }

        if (!tight) memo.set(key, res);
        return res;
    }

    for (let x = 0; x <= 9; x++) {
        for (let y = x; y <= 9; y++) {
            memo.clear();
            total += dfs(0, 0, true, false, x, y);
        }
    }

    return total;
}

