const input = fs.readFileSync(0, 'utf8').trim();
if (input.length === 0) process.exit(0);
const n = BigInt(input);

function countUndoubtedlyLucky(n) {
    const s = n.toString();
    const len = s.length;

    // Precompute powers of 10 up to 10 digits
    const pow10 = [1n];
    for (let i = 1; i <= 10; i++) pow10.push(pow10[i - 1] * 10n);

    // Count numbers with length < len
    let total = 0n;
    for (let L = 1; L < len; L++) {
        // All digits same: 9 choices (1-9)
        let count = 9n;
        // Two distinct digits:
        // choose unordered pair {x,y} with at least one non-zero
        // total unordered pairs = 45, subtract pairs with both zero or both non-zero? Easier: brute.
        let pairCount = 0n;
        for (let x = 0; x <= 9; x++) {
            for (let y = x + 1; y <= 9; y++) {
                if (x !== 0 || y !== 0) pairCount++;
            }
        }
        // For each pair, number of sequences of length L using both digits at least once
        // total sequences = 2^L, subtract 2 sequences all x or all y
        const seq = (1n << BigInt(L)) - 2n;
        count += pairCount * seq;
        total += count;
    }

    // Count numbers with length == len and <= n
    const digits = s.split('').map(ch => parseInt(ch, 10));

    // Helper: count numbers of length len, <= n, using digits from set S (size 1 or 2)
    function countForSet(a, b) {
        // a,b are digits, a may be null if single-digit set
        const set = b === null ? [a] : [a, b];
        const size = set.length;

        // Leading digit cannot be 0
        if (set.every(d => d === 0)) return 0n;
        if (set.includes(0) && size === 1) return 0n;

        let count = 0n;

        function dfs(pos, tight, usedMask) {
            if (pos === len) {
                // For size 1: any number with that digit is valid
                if (size === 1) return 1n;
                // For size 2: must use both digits at least once
                return usedMask === 3 ? 1n : 0n;
            }
            const limit = tight ? digits[pos] : 9;
            let res = 0n;
            for (let d of set) {
                if (pos === 0 && d === 0) continue;
                if (d > limit) continue;
                const ntight = tight && (d === limit);
                let nmask = usedMask;
                if (size === 2) {
                    if (d === set[0]) nmask |= 1;
                    else nmask |= 2;
                }
                res += dfs(pos + 1, ntight, nmask);
            }
            return res;
        }

        return dfs(0, true, 0);
    }

    // Single-digit sets
    for (let d = 1; d <= 9; d++) {
        total += countForSet(d, null);
    }

    // Two-digit sets
    for (let x = 0; x <= 9; x++) {
        for (let y = x + 1; y <= 9; y++) {
            if (x === 0 && y === 0) continue;
            total += countForSet(x, y);
        }
    }

    return total;
}

