const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();
if (input.length === 0) process.exit(0);
const n = BigInt(input);

function countUndoubtedlyLucky(n) {
    const s = n.toString();
    const len = s.length;
    let count = 0n;

    // Count numbers with length less than len
    for (let L = 1; L < len; L++) {
        const total = 10n ** BigInt(L);
        const bad = 9n * (10n ** BigInt(L - 1)); // numbers with all digits equal
        count += total - bad;
    }

    // Count numbers with length equal to len and <= n
    function dfs(pos, tight, usedMask, leadingZero, val) {
        if (pos === len) {
            if (leadingZero) return; // exclude 0
            // Check if number is undoubtedly lucky
            // usedMask has bits for digits used
            // Count distinct digits
            let bits = usedMask;
            let distinct = 0;
            while (bits) {
                bits &= (bits - 1);
                distinct++;
                if (distinct > 2) break;
            }
            if (distinct <= 2) count++;
            return;
        }

        const limit = tight ? Number(s[pos]) : 9;
        for (let d = 0; d <= limit; d++) {
            const ntight = tight && (d === limit);
            const nleadingZero = leadingZero && (d === 0);
            let nmask = usedMask;
            if (!nleadingZero) {
                nmask |= (1 << d);
            }
            dfs(pos + 1, ntight, nmask, nleadingZero, val);
        }
    }

    dfs(0, true, 0, true, 0n);
    return count;
}

